    ok("a pair with an arm missing in a set gives no effect for that set (F1 and F9 have no flights here, so no row)", rows.length === 2 && rows.every((r) => r.feature === "F8"));
    ok("rows come in feature order, then sea order as given", same(rows.map((r) => r.sea), ["R3D30", "W"]));
    // the effect uses reached only: n is ignored
    ok("the effect is k of the arm with the feature minus k of the arm without (the rows' n does not enter)", (() => { const t2 = P.armTable([...flights({ "inc@W": { s1: 5, s2: 5 } }, 10), ...flights({ "e30@W": { s1: 8, s2: 9 } }, 10)], defs).table; const r = P.featureEffects(t2, pairs, ["W"])[0]; return same(r.effects, [3, 4]); })());
    // aliases: inc and inc2 are one arm, so the single pair is counted once
    ok("aliases do not double a pair: inc flown as inc in one set and as inc2 in another is one arm, one pair per set", (() => { const t2 = P.armTable(flights({ "inc@W": { s1: 10 }, "inc2@W": { s2: 20 }, "e30@W": { s1: 15, s2: 21 } }), defs).table; const r = P.featureEffects(t2, pairs, ["W"])[0]; return r.n === 2 && same(r.effects, [5, 1]) && same(r.pairs, [1, 1]); })());
    // the set effect is the MEAN over a set's pairs: two F8 pairs in one set (inc > e30 and inc > e12) with effects 4 and 2 -> 3
    const defs2 = { inc: sp([1, 1], FORGET), e30: sp([1, 1], EV30), e12: sp([1, 1], clearOf(12, 12, { evidence: true })) }, pairs2 = P.matchPairs(defs2);
    ok("!! the set's effect is the MEAN over its matched pairs, not the sum: inc > e30 (+4) and inc > e12 (+2) in one set is +3, two pairs", (() => { const t2 = P.armTable(flights({ "inc@W": { s1: 10 }, "e30@W": { s1: 14 }, "e12@W": { s1: 12 } }), defs2).table; const r = P.featureEffects(t2, pairs2, ["W"])[0]; return pairs2.length === 2 && r.effects[0] === 3 && r.pairs[0] === 2; })());
    ok("a set whose pairs cancel (+1 and -1) is a ZERO set, not a positive or a negative one", (() => { const t2 = P.armTable(flights({ "inc@W": { s1: 10 }, "e30@W": { s1: 11 }, "e12@W": { s1: 9 } }), defs2).table; const r = P.featureEffects(t2, pairs2, ["W"])[0]; return r.effects[0] === 0 && r.zero === 1 && r.pos === 0 && r.neg === 0; })());
