    ok("the ghost's variants are separate rows with their variant label (g plain +2, gc carrying -3 against e30), and the carry against the same ghost is an F2 row (gc minus g = -5)", (() => { const t2 = P.armTable(flights({ "e30@W": { s1: 10, s2: 10 }, "g@W": { s1: 12, s2: 12 }, "gc@W": { s1: 7, s2: 7 } }), defs3).table; const r = P.featureEffects(t2, pairs3, ["W"]), f1 = r.filter((x) => x.feature === "F1"), f2 = r.filter((x) => x.feature === "F2"); return r.length === 3 && f1.length === 2 && f2.length === 1 && f1.map((x) => x.variant).sort().join("|") === [VAR0, "zone all at mark nbr false carry true min 4 life 60"].sort().join("|") && f1.find((x) => x.variant === VAR0).mean === 2 && f1.find((x) => x.variant.includes("carry true")).mean === -3 && f2[0].mean === -5 && f2[0].variant === ""; })());
