    ok("call: |mean| = half-width is NOT excluded (strict): NOT SEPARABLE; a hair over it is SEEN", P.call(R({ mean: 2, half: 2 })) === "not separable" && P.call(R({ mean: 2.0001, half: 2 })) === "seen" && P.call(R({ mean: -2, half: 2, pos: 0, neg: 5 })) === "not separable" && P.call(R({ mean: -2.0001, half: 2, pos: 0, neg: 5 })) === "seen");
    ok("!! call: the sign share is 80% at the edge: 4 positive of 5 nonzero is SEEN (5 x 4 >= 5 x 4); 3 of 4 nonzero (75%) with 5 sets is SUGGESTED; 8 of 10 is SEEN; 7 of 9 (77.8%) is SUGGESTED", P.call(R({ n: 5, pos: 4, neg: 1 })) === "seen" && P.call(R({ n: 5, pos: 3, neg: 1 })) === "suggested" && P.call(R({ n: 10, pos: 8, neg: 2 })) === "seen" && P.call(R({ n: 10, pos: 7, neg: 2 })) === "suggested");
    ok("call: the share is of the NONZERO sets: 4 positive and 3 zero (7 sets) is 100% and SEEN; 4 positive, 1 negative, 2 zero is 80% and SEEN; 3 positive, 1 negative, 3 zero is 75% and SUGGESTED", P.call(R({ n: 7, pos: 4, neg: 0 })) === "seen" && P.call(R({ n: 7, pos: 4, neg: 1 })) === "seen" && P.call(R({ n: 7, pos: 3, neg: 1 })) === "suggested");
    ok("call: the majority may be negative (a negative effect is SEEN by the same share rule); 4 negative of 5 is SEEN", P.call(R({ mean: -4, pos: 1, neg: 4 })) === "seen" && P.call(R({ mean: -4, pos: 2, neg: 3 })) === "suggested");
    ok("call: one set (no interval) is NOT SEPARABLE even when a half-width is given; two sets can only be suggested", P.call(R({ n: 1, half: NaN, pos: 1 })) === "not separable" && P.call(R({ n: 1, pos: 1 })) === "not separable" && P.call(R({ n: 2, half: 1, pos: 2 })) === "suggested");
    ok("call: nothing nonzero (all zero sets) is NOT SEPARABLE even with a zero half-width", P.call(R({ mean: 0, half: 0, pos: 0, neg: 0 })) === "not separable");
    // the whole pipeline on the scenarios of the rule: 4 of 5 positive
    // effects 6 7 5 8 -1: mean 5, deviations 1 2 0 3 -6, squares 50 / 4 = 12.5, sd 3.5355, half = 2.776 * 3.5355 / 2.2361 = 4.3892: |5| > 4.39, share 4/5 -> SEEN
    const mk = (eff, names = ["inc", "e30"]) => { const sets = {}, setsB = {}; eff.forEach((e, i) => { sets["s" + (i + 1)] = 100; setsB["s" + (i + 1)] = 100 + e; }); return P.armTable(flights({ [names[0] + "@W"]: sets, [names[1] + "@W"]: setsB }), defs).table; };
    const run = (eff) => P.featureEffects(mk(eff), pairs, ["W"]).find((r) => r.feature === "F8");
    const q = run([6, 7, 5, 8, -1]);
    ok("!! 4 positive and 1 negative of five (effects 6 7 5 8 -1): mean 5, sd 3.5355, half-width 4.3892, share 80%: SEEN", near(q.mean, 5) && near(q.sd, Math.sqrt(12.5), 1e-9) && near(q.half, 2.776 * Math.sqrt(12.5) / Math.sqrt(5), 1e-9) && q.pos === 4 && q.neg === 1 && q.call === "seen");
    // effects 20 20 20 20 -2 -2: mean 12.667; deviations 7.333 x4 and -14.667 x2: 53.78 * 4 + 215.11 * 2 = 645.33, / 5 = 129.07, sd 11.361, half 2.571 * 11.361 / 2.4495 = 11.925 < 12.667 -> excludes; share 4 of 6 = 66.7% -> SUGGESTED
    const q2 = run([20, 20, 20, 20, -2, -2]);
    ok("!! 4 positive and 2 negative of six (effects 20 20 20 20 -2 -2): the interval excludes 0 (mean 12.67, half-width 11.93) but the share is 66.7%: SUGGESTED", q2.call === "suggested" && q2.n === 6 && near(q2.half, 2.571 * Math.sqrt(645.3333333333 / 5) / Math.sqrt(6), 1e-5) && q2.pos === 4 && q2.neg === 2);
    // 5, 5, 5, 5, 0: mean 4, sd 2.2361, half 2.776: excludes; 4 positive 0 negative -> SEEN
