    ok("the half-width uses t at n - 1 degrees of freedom: two sets use 12.706, so 4 and 6 (mean 5, sd 1.414, half 12.706) are NOT SEPARABLE", (() => { const r = run([4, 6]); return near(r.half, 12.706, 1e-9) && r.call === "not separable"; })());
