    ok("PA2: with F2 rows it reads them (a seen F2 row misses it)", score(mod((r) => r.push(row("F2", "W", "seen", 3)))).PA2.held === false && score(mod((r) => r.push(row("F2", "W", "suggested", 3)))).PA2.held === false);
    ok("!! PA2 with NO F2 row reads the F1 rows whose ghost carries: a seen carrying F1 row misses it, a not separable one holds it, none at all is missed", (() => { const noF2 = (extra) => [row("F1", "W", "not separable", 1), ...extra]; const car = (call) => row("F1", "R3D30", call, 3, { variant: "zone all at mark nbr false carry true min 4 life 60" }); return score(noF2([car("seen")])).PA2.held === false && score(noF2([car("not separable")])).PA2.held === true && score(noF2([])).PA2.held === false && /F1 rows whose ghost carries/.test(score(noF2([car("not separable")])).PA2.detail); })());
    ok("PA2 with F2 rows does NOT also read the carrying F1 rows", score([row("F2", "W", "not separable", 1), row("F1", "R3D30", "seen", 3, { variant: "zone all at mark nbr false carry true min 4 life 60" })]).PA2.held === true);
    // PA3
