    ok("PA3 needs EVERY F3 row to be inside: one bad row among good ones misses", score(mod((r) => r.push(row("F3", "W", "seen", -9)))).PA3.held === false && score(mod((r) => r.push(row("F3", "W", "seen", -3)))).PA3.held === true);
