    ok("!! the report counts the calls apart (2 seen, 3 suggested, 4 not separable of 9), shows an interval from two sets on and `none` for one, `-` for no variant, and the variant when there is one", fab.includes("(B) THE EFFECT OF ONE FEATURE: 9 rows (feature, variant, sea) with at least one set; seen 2, suggested 3, not separable 4; the registration's grid is 9 features x 6 seas = 54, unadjusted") && fab.includes("F1 | v | W | 5 | 1.00 | 0.50 to 1.50 | 5/0/0 | seen") && fab.includes("F2 | - | P | 2 | 2.00 | 1.00 to 3.00 | 2/0/0 | suggested") && fab.includes("F3 | - | D30 | 1 | -1.50 | none | 0/1/0 | not separable") && fab[0] === "POOLED READING (follow-up 59): 2 sets (a to b), the flights already in the repository; no flight was made");
    // the command
    const io = (o = {}) => { const log = []; return { log, o: { out: "/tmp/x.txt", exists: () => false, writeFile: (f, t) => log.push(["write", f, t]), log: (m) => log.push(["log", m]), err: (m) => log.push(["err", m]), print: (t) => log.push(["print", t]), run: () => ({ text: "TABLE\n" }), ...o } }; };
    const a = io(); const rc1 = P.main([], a.o);
    ok("main with no flag prints the table and writes nothing", rc1 === 0 && same(a.log, [["print", "TABLE\n"]]));
    const b = io(); const rc2 = P.main(["--write"], b.o);
    ok("main --write writes the table to the file and says where, once", rc2 === 0 && same(b.log, [["write", "/tmp/x.txt", "TABLE\n"], ["log", "wrote /tmp/x.txt"]]));
