    ok("!! run as a script (a child process with a flag it does not know, so that nothing is read): the module calls main with the arguments after the script, and its exit code is the process's: status 1, the usage message on stderr, nothing on stdout", cp.status === 1 && cp.stderr.trim() === "usage: node tools/ship/subSensedPool.mjs [--write]   (not understood: --bogus)" && cp.stdout === "", `status ${cp.status}`);
    const cp2 = spawnSync(process.execPath, [fileURLToPath(new URL("./subSensedPool.mjs", import.meta.url))], { encoding: "utf8", maxBuffer: 1 << 26 });
    ok("!! run as a script with no flag: it prints the table and exits 0 (only the first line is looked at here; no count, effect or interval is read or compared)", cp2.status === 0 && cp2.stdout.split("\n")[0] === "POOLED READING (follow-up 59): 51 sets (held13 to held63), the flights already in the repository; no flight was made" && cp2.stderr === "", `status ${cp2.status}`);
